import json


class StateFile:
    def __init__(self):
        self.version = 1
        self.resources = {}

    def record(self, address, attrs):
        self.resources[address] = attrs
        self.version += 1

    def show(self, address):
        return self.resources.get(address)

    def dump(self):
        return json.dumps({"version": self.version, "resources": self.resources}, sort_keys=True)


state = StateFile()
state.record("aws_instance.web", {"id": "i-001", "instance_type": "t2.micro"})

print(state.show("aws_instance.web"))
print("state version:", state.version)
